  ]
}

{
  "type": "object",
  "properties": {
    "goal": {
      "type": "string",
      "description": "Investigation goal for this checkpoint"
    }
  }
}

{
  "type": "object",
  "properties": {
    "report": {
      "type": "string",
      "description": "Investigation findings retained after the rewind"
    }
  },
  "required": [
    "report"
  ]
}

{
  "type": "object",
  "properties": {
    "target": {
      "type": "string",
